	}

	if len(entry.Steps) != 2 {
		t.Fatalf("len(Steps) = %d, want 2", len(entry.Steps))
	}

	// Steps sorted alphabetically: cleanup, process_sessions
	if entry.Steps[0].Name != "cleanup" {
