	ps := entry.Steps[1]
	if ps.Name != "process_sessions" {
		t.Errorf("Steps[1].Name = %q, want %q", ps.Name, "process_sessions")
	}
	if ps.DurationMs != 300 {
		t.Errorf("Steps[1].DurationMs = %d, want %d", ps.DurationMs, 300)
