 105→+		if err := json.Unmarshal(dRaw, &entry.DurationMs); err != nil {
 106→+			return nil
 107→+		}
 108→+	}
 109→+
 110→+	// Extract error flag
 111→+	if errRaw, ok := raw["error"]; ok {
 112→+		if err := json.Unmarshal(errRaw, &entry.Error); err != nil {
 113→+			return nil
 114→+		}
 115→+	}
 116→+
 117→+	// Extract time
 118→+	if tRaw, ok := raw["time"]; ok {
 119→+		var ts string
 120→+		if err := json.Unmarshal(tRaw, &ts); err == nil {
 121→+			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
 122→+				entry.Time = parsed
 123→+			}
 124→+		}
 125→+	}
 126→+
 127→+	// Extract steps by finding keys matching "steps.*_ms"
 128→+	stepDurations := make(map[string]int64)
 129→+	stepErrors := make(map[string]bool)
 130→+
 131→+	for key, val := range raw {
 132→+		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
 133→+			name := strings.TrimPrefix(key, "steps.")
 134→+			name = strings.TrimSuffix(name, "_ms")
 135→+
 136→+			var ms int64
 137→+			if err := json.Unmarshal(val, &ms); err == nil {
 138→+				stepDurations[name] = ms
 139→+			}
 140→+		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
 141→+			name := strings.TrimPrefix(key, "steps.")
 142→+			name = strings.TrimSuffix(name, "_err")
 143→+
 144→+			var errFlag bool
 145→+			if err := json.Unmarshal(val, &errFlag); err == nil {
 146→+				stepErrors[name] = errFlag
 147→+			}
 148→+		}
 149→+	}
 150→+
 151→+	// Separate parent steps from sub-steps.
 152→+	// A key like "foo.0" is a sub-step of "foo" if "foo" also exists as a parent
 153→+	// and the last segment is a non-negative integer.
 154→+	subStepDurations := make(map[string]map[int]int64) // parent -> index -> ms
 155→+	subStepErrors := make(map[string]map[int]bool)     // parent -> index -> err
 156→+	parentStepDurations := make(map[string]int64)
 157→+	parentStepErrors := make(map[string]bool)
 158→+
 159→+	for name, ms := range stepDurations {
 160→+		if parent, idx, ok := parseSubStepKey(name, stepDurations); ok {
 161→+			if subStepDurations[parent] == nil {
 162→+				subStepDurations[parent] = make(map[int]int64)
 163→+			}
 164→+			subStepDurations[parent][idx] = ms
 165→+			if stepErrors[name] {
 166→+				if subStepErrors[parent] == nil {
 167→+					subStepErrors[parent] = make(map[int]bool)
 168→+				}
 169→+				subStepErrors[parent][idx] = true
 170→+			}
 171→+		} else {
 172→+			parentStepDurations[name] = ms
 173→+			parentStepErrors[name] = stepErrors[name]
 174→+		}
 175→+	}
 176→+
 177→+	// Build steps slice sorted alphabetically by name
 178→+	steps := make([]traceStep, 0, len(parentStepDurations))
 179→+	for name, ms := range parentStepDurations {
 180→+		step := traceStep{
 181→+			Name:       name,
 182→+			DurationMs: ms,
 183→+			Error:      parentStepErrors[name],
 184→+		}
 185→+
 186→+		// Attach sub-steps if any, sorted by numeric index
 187→+		if subs, ok := subStepDurations[name]; ok {
 188→+			indices := make([]int, 0, len(subs))
 189→+			for idx := range subs {
 190→+				indices = append(indices, idx)
 191→+			}
 192→+			sort.Ints(indices)
 193→+
 194→+			subList := make([]traceStep, 0, len(subs))
 195→+			for _, idx := range indices {
 196→+				subList = append(subList, traceStep{
 197→+					Name:       fmt.Sprintf("%s.%d", name, idx),
 198→+					DurationMs: subs[idx],
 199→+					Error:      subStepErrors[name][idx],
 200→+				})
 201→+			}
 202→+			step.SubSteps = subList
 203→+		}
 204→+
 205→+		steps = append(steps, step)
 206→+	}
 207→+	sort.Slice(steps, func(i, j int) bool {
 208→+		return steps[i].Name < steps[j].Name
 209→+	})
 210→+
 211→+	entry.Steps = steps
 212→+
 213→+	return entry
 214→+}
 215→+
 216→+// parseSubStepKey checks if a step name like "foo.0" is a sub-step of "foo".
 217→+// Returns the parent name, index, and true if it is a sub-step.
 218→+// A name is a sub-step if: the last segment after the final "." is a non-negative
 219→+// integer AND the parent name exists in allSteps.
 220→+func parseSubStepKey(name string, allSteps map[string]int64) (string, int, bool) {
 221→+	lastDot := strings.LastIndex(name, ".")
 222→+	if lastDot < 0 {
 223→+		return "", 0, false
 224→+	}
 225→+	parent := name[:lastDot]
 226→+	suffix := name[lastDot+1:]
 227→+	idx, err := strconv.Atoi(suffix)
 228→+	if err != nil || idx < 0 {
 229→+		return "", 0, false
 230→+	}
 231→+	if _, exists := allSteps[parent]; !exists {
 232→+		return "", 0, false
 233→+	}
 234→+	return parent, idx, true
 235→+}
 236→+
 237→+// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
 238→+// ordered newest first. If hookFilter is non-empty, only entries with a matching
 239→+// Op field are included.
 240→+func collectTraceEntries(logFile string, last int, hookFilter string) ([]traceEntry, error) {
 241→+	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
 242→+	if err != nil {
 243→+		if errors.Is(err, os.ErrNotExist) {
 244→+			return nil, nil
 245→+		}
 246→+		return nil, fmt.Errorf("opening log file: %w", err)
 247→+	}
 248→+	defer f.Close()
 249→+
 250→+	var entries []traceEntry
 251→+
 252→+	scanner := bufio.NewScanner(f)
 253→+	for scanner.Scan() {
 254→+		entry := parseTraceEntry(scanner.Text())
 255→+		if entry == nil {
 256→+			continue
 257→+		}
 258→+		if hookFilter != "" && entry.Op != hookFilter {
 259→+			continue
 260→+		}
 261→+		entries = append(entries, *entry)
 262→+	}
 263→+
 264→+	if err := scanner.Err(); err != nil {
 265→+		return nil, fmt.Errorf("reading log file: %w", err)
 266→+	}
 267→+
 268→+	// Take the last N entries
 269→+	if len(entries) > last {
 270→+		entries = entries[len(entries)-last:]
 271→+	}
 272→+
 273→+	// Reverse so newest entries are first
 274→+	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
 275→+		entries[i], entries[j] = entries[j], entries[i]
 276→+	}
 277→+
 278→+	return entries, nil
 279→+}
 280→+
 281→+// renderTraceEntries writes a formatted table of trace entries to w.
 282→+// If entries is empty, it prints a help message about enabling traces.
 283→+func renderTraceEntries(w io.Writer, entries []traceEntry) {
 284→+	if len(entries) == 0 {
 285→+		fmt.Fprintln(w, "No trace entries found.")
 286→+		fmt.Fprintln(w, `Traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
 287→+		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
 288→+		return
 289→+	}
 290→+
 291→+	for i, entry := range entries {
 292→+		if i > 0 {
 293→+			fmt.Fprintln(w)
 294→+		}
 295→+
 296→+		// Header line: op  duration  [timestamp]
 297→+		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
 298→+		if !entry.Time.IsZero() {
 299→+			header += "  " + entry.Time.Format(time.RFC3339)
 300→+		}
 301→+		fmt.Fprintln(w, header)
 302→+		fmt.Fprintln(w)
 303→+
 304→+		if len(entry.Steps) == 0 {
 305→+			continue
 306→+		}
 307→+
 308→+		// Compute max name display width (at least len("STEP")).
 309→+		// Sub-steps are indented 5 extra display columns relative to parent rows
 310→+		// ("    " + "├─ " = 7 display cols vs "  " = 2 display cols).
 311→+		const subExtraIndent = 5
 312→+		nameWidth := len("STEP")
 313→+		for _, s := range entry.Steps {
 314→+			if len(s.Name) > nameWidth {
 315→+				nameWidth = len(s.Name)
 316→+			}
 317→+			for _, sub := range s.SubSteps {
 318→+				if needed := len(sub.Name) + subExtraIndent; needed > nameWidth {
 319→+					nameWidth = needed
 320→+				}
 321→+			}
 322→+		}
 323→+
 324→+		// Column header
 325→+		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
 326→+
 327→+		// Step rows
 328→+		for _, s := range entry.Steps {
 329→+			dur := fmt.Sprintf("%dms", s.DurationMs)
 330→+			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
 331→+			if s.Error {
 332→+				line += "  x"
 333→+			}
 334→+			fmt.Fprintln(w, line)
 335→+
 336→+			// Sub-step rows with ASCII tree connectors.
 337→+			// Pad manually to avoid multi-byte UTF-8 box-drawing chars
 338→+			// (├─, └─) breaking Go's byte-based %-*s alignment.
 339→+			for i, sub := range s.SubSteps {
 340→+				connector := "├─"
 341→+				if i == len(s.SubSteps)-1 {
 342→+					connector = "└─"
 343→+				}
 344→+				subDur := fmt.Sprintf("%dms", sub.DurationMs)
 345→+				pad := nameWidth - subExtraIndent - len(sub.Name)
 346→+				if pad < 0 {
 347→+					pad = 0
 348→+				}
 349→+				subLine := fmt.Sprintf("    %s %s%s  %8s", connector, sub.Name, strings.Repeat(" ", pad), subDur)
 350→+				if sub.Error {
 351→+					subLine += "  x"
 352→+				}
 353→+				fmt.Fprintln(w, subLine)
 354→+			}
 355→+		}
 356→+	}
 357→+}
