 375→+func newTraceCmd() *cobra.Command {
 376→+	var last int
 377→+	var hookFilter string
 378→+
 379→+	cmd := &cobra.Command{
 380→+		Use:   "trace",
 381→+		Short: "Show hook performance traces",
 382→+		Long: `Show timing information for recent hook invocations.
 383→+
 384→+Traces are emitted at DEBUG log level. To enable them, either:
 385→+  - Set ENTIRE_LOG_LEVEL=DEBUG in your shell profile
 386→+  - Add "log_level": "DEBUG" to .entire/settings.json
 387→+
 388→+Examples:
 389→+  entire trace                     Show the most recent hook trace
 390→+  entire trace --last 5            Show the last 5 hook traces
 391→+  entire trace --hook post-commit  Show only post-commit hook traces`,
 392→+		RunE: func(cmd *cobra.Command, _ []string) error {
 393→+			if last < 1 {
 394→+				return fmt.Errorf("--last must be at least 1, got %d", last)
 395→+			}
 396→+
 397→+			repoRoot, err := paths.WorktreeRoot(cmd.Context())
 398→+			if err != nil {
 399→+				cmd.SilenceUsage = true
 400→+				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
 401→+				return NewSilentError(fmt.Errorf("not a git repository: %w", err))
 402→+			}
 403→+
 404→+			logFile := filepath.Join(repoRoot, logging.LogsDir, "entire.log")
 405→+
 406→+			entries, err := collectTraceEntries(logFile, last, hookFilter)
 407→+			if err != nil {
 408→+				return fmt.Errorf("collecting trace entries: %w", err)
 409→+			}
 410→+
 411→+			renderTraceEntries(cmd.OutOrStdout(), entries)
 412→+			return nil
 413→+		},
 414→+	}
 415→+
 416→+	cmd.Flags().IntVar(&last, "last", 1, "Show last N hook invocations")
 417→+	cmd.Flags().StringVar(&hookFilter, "hook", "", "Filter by hook type (e.g. post-commit, prepare-commit-msg, pre-push)")
 418→+
 419→+	return cmd
 420→+}
