 918→+// LoopSpan wraps a Span that groups loop iterations. Each call to Iteration
 919→+// creates a child span representing one pass through the loop.
 920→+//
 921→+// Usage:
 922→+//
 923→+//	ctx, loop := perf.StartLoop(ctx, "process_sessions")
 924→+//	for _, item := range items {
 925→+//	    iterCtx, iterSpan := loop.Iteration(ctx)
 926→+//	    doWork(iterCtx, item)
 927→+//	    iterSpan.End()
 928→+//	}
 929→+//	loop.End()
 930→+type LoopSpan struct {
 931→+	span *Span
 932→+}
 933→+
 934→+// StartLoop begins a new loop span. The returned context contains the loop span
 935→+// and should be passed to Iteration. Call loop.End() after the loop completes.
 936→+func StartLoop(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *LoopSpan) {
 937→+	ctx, s := Start(ctx, name, attrs...)
 938→+	return ctx, &LoopSpan{span: s}
 939→+}
 940→+
 941→+// Iteration creates a child span for a single loop iteration. The caller must
 942→+// call End() on the returned span when the iteration completes.
 943→+func (l *LoopSpan) Iteration(ctx context.Context) (context.Context, *Span) {
 944→+	return Start(ctx, l.span.name)
 945→+}
 946→+
 947→+// End completes the loop span by ending the underlying span.
 948→+// Note: this does not itself iterate over and end unended iteration spans;
 949→+// any automatic cleanup of child spans occurs when the root span is ended.
 950→+func (l *LoopSpan) End() {
 951→+	l.span.End()
 952→+}
