119→// childStepKey returns a unique key for a child span name.
120→// First occurrence keeps the original name; subsequent get .1, .2, etc.
121→// The seen map is updated in place.
122→func childStepKey(name string, seen map[string]int) string {
123→	n := seen[name]
124→	seen[name] = n + 1
