131→// LoopSpan wraps a Span that groups loop iterations. Each call to Iteration
132→// creates a child span representing one pass through the loop.
133→//
134→// Usage:
135→//
136→//	ctx, loop := perf.StartLoop(ctx, "process_sessions")
137→//	for _, item := range items {
138→//	    iterCtx, iterSpan := loop.Iteration(ctx)
139→//	    doWork(iterCtx, item)
