147→// StartLoop begins a new loop span. The returned context contains the loop span
148→// and should be passed to Iteration. Call loop.End() after the loop completes.
149→func StartLoop(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *LoopSpan) {
150→	ctx, s := Start(ctx, name, attrs...)
151→	return ctx, &LoopSpan{span: s}
152→}
153→
154→// Iteration creates a child span for a single loop iteration. The caller must
155→// call End() on the returned span when the iteration completes.
156→func (l *LoopSpan) Iteration(ctx context.Context) (context.Context, *Span) {
157→	return Start(ctx, l.span.name)
