160→// End completes the loop span by ending the underlying span.
161→// Note: this does not itself iterate over and end unended iteration spans;
162→// any automatic cleanup of child spans occurs when the root span is ended.
163→func (l *LoopSpan) End() {
164→	l.span.End()
165→}
